	/** Requests cancellation without retiring any native resources; close still drains every admitted call. */
	@InternalUseOnly
	public final void requestShutdown() {
		List<Closeable> cancelledInputs = null;
		synchronized (operationLock) {
			cancellation.cancel();
			// Result pulls publish their puller and then read the signal without this monitor; order the release of
			// cancellation before reading their puller slots. Attention makes a finishing pull wait for this monitor,
			// so an interrupt can only land while that pull is still in progress.
			VarHandle.fullFence();
			raiseAttention();
			try {
				for (SailBaseIteration<?, ?> result : registeredResults()) {
					result.interruptPuller();
				}
			} finally {
				lowerAttention();
			}
			for (OperationThread registration = activeOperationThreads; registration != null; registration = registration.next) {
				if (registration.thread != Thread.currentThread()) {
					// Registration removal uses this monitor too: never interrupt a task's reused pool thread.
					registration.thread.interrupt();
				}
			}
			for (ExternalWorkload workload = activeExternalWorkloads; workload != null; workload = workload.next) {
				if (workload.thread != Thread.currentThread()) {
					workload.thread.interrupt();
					if (workload.cancellableInput != null) {
						if (cancelledInputs == null) {
							cancelledInputs = new ArrayList<>();
						}
						// Claimed under the monitor, so normal completion can no longer hand it back unclosed.
						cancelledInputs.add(workload.cancellableInput);
						workload.cancellableInput = null;
					}
				}
			}
		}
		if (cancelledInputs != null) {
			// Outside the monitor: caller input may block in close or call back into this connection.
			for (Closeable input : cancelledInputs) {
				try {
					input.close();
				} catch (IOException | RuntimeException failure) {
					logger.debug("Failed to close cancelled upload input", failure);
				}
			}
		}
	}

	/**
	 * Registers caller-driven work that runs between Sail callbacks on this thread, such as a parser reading upload
	 * input. Shutdown interrupts the registered thread. The workload owns no admitted native call, so connection close
	 * never waits for it, and its callbacks after cancellation are rejected like any other new operation. Close the
	 * returned registration in a finally block.
	 *
	 * @param cancellableInput input the workload reads, or {@code null}. It is closed only if shutdown cancels the
	 *                         workload, which unblocks a read that ignores interruption; normal completion never closes
	 *                         it.
	 * @return the registration, or {@code null} when this connection is already closed and the workload's first
	 *         operation will report that as before
	 * @throws SailException if shutdown already cancelled this connection
	 */
	@InternalUseOnly
	public final ExternalWorkload beginExternalWorkload(Closeable cancellableInput) throws SailException {
		synchronized (operationLock) {
			if (!((boolean) IS_OPEN.getAcquire(this))) {
				return null;
			}
			checkOperationCancellation();
			ExternalWorkload workload = new ExternalWorkload(Thread.currentThread(), cancellableInput);
			workload.next = activeExternalWorkloads;
			if (activeExternalWorkloads != null) {
				activeExternalWorkloads.previous = workload;
			}
			activeExternalWorkloads = workload;
			return workload;
		}
	}

	/** A registration from {@link #beginExternalWorkload()}; closing it is idempotent. */
	@InternalUseOnly
	public final class ExternalWorkload implements AutoCloseable {
		private final Thread thread;
		private Closeable cancellableInput;
		private ExternalWorkload previous;
		private ExternalWorkload next;
		private boolean closed;

		private ExternalWorkload(Thread thread, Closeable cancellableInput) {
			this.thread = thread;
			this.cancellableInput = cancellableInput;
		}

		@Override
		public void close() {
			synchronized (operationLock) {
				if (closed) {
					return;
				}
				closed = true;
				cancellableInput = null;
				if (previous == null) {
					activeExternalWorkloads = next;
				} else {
					previous.next = next;
				}
				if (next != null) {
					next.previous = previous;
				}
				previous = null;
				next = null;
			}
		}
	}

	final boolean hasCurrentOperation() {
		synchronized (operationLock) {
			for (OperationThread registration = activeOperationThreads; registration != null; registration = registration.next) {
				if (registration.thread == Thread.currentThread()) {
					return true;
				}
			}
			for (SailBaseIteration<?, ?> result : registeredResults()) {
				if (result.isPulledBy(Thread.currentThread())) {
					return true;
				}
			}
			return closingThread == Thread.currentThread();
		}
	}

